import {calculate} from './calc.mjs';
const $=id=>document.getElementById(id), blank=()=>({gpa:'',type:'expected',credits:'20'});
let state={years:3,scale:5,weighted:false,rows:Array.from({length:12},blank)};
try {const old=JSON.parse(localStorage.getItem('cgpa-plan'));if(old&&[2,3,4,5,6].includes(old.years)&&[4,5].includes(old.scale)&&Array.isArray(old.rows)&&old.rows.length===12&&old.rows.every(r=>r&&['actual','expected'].includes(r.type)&&typeof r.gpa==='string'&&typeof r.credits==='string'))state=old;}catch{}
function render(){ $('years').value=state.years;$('scale').value=state.scale;$('weighted').checked=state.weighted;$('semesters').innerHTML='';for(let y=0;y<state.years;y++){const group=document.createElement('div');group.className='year';group.innerHTML=`<h3>Year ${y+1}</h3>`;for(let s=0;s<2;s++){const i=y*2+s,r=state.rows[i],row=document.createElement('div');row.className='semester';row.innerHTML=`<span>Semester ${s+1}</span><label class="sr" for="gpa-${i}">Year ${y+1} semester ${s+1} GPA</label><input id="gpa-${i}" type="number" inputmode="decimal" min="0" max="${state.scale}" step="0.01" placeholder="0.00"><label class="sr" for="type-${i}">Result type</label><select id="type-${i}"><option value="actual">Actual</option><option value="expected">Expected</option></select>${state.weighted?`<label class="credits">Credits<input id="credits-${i}" type="number" min="0.1" step="any" aria-label="Year ${y+1} semester ${s+1} credit units"></label>`:''}`;group.append(row);row.querySelector('input').value=r.gpa;row.querySelector('select').value=r.type;row.querySelector('input').addEventListener('input',e=>{r.gpa=e.target.value;update()});row.querySelector('select').addEventListener('change',e=>{r.type=e.target.value;update()});if(state.weighted){row.querySelector('.credits input').value=r.credits;row.querySelector('.credits input').addEventListener('input',e=>{r.credits=e.target.value;update()})}}$('semesters').append(group)}update()}
function update(){const rows=state.rows.slice(0,state.years*2),r=calculate(rows,state.scale,state.weighted),fmt=v=>v==null?'—':(Math.round((v+Number.EPSILON)*100)/100).toFixed(2);$('maximum').textContent=fmt(r.maximum);$('current').textContent=fmt(r.current);$('projected').textContent=fmt(r.projected);$('outof').textContent=state.scale.toFixed(1);$('max-note').textContent=r.invalid?'Enter GPAs within your scale and positive credit units.':r.count===rows.length?'All semesters are complete. This is your final CGPA.':`If you score ${state.scale.toFixed(1)} in all ${rows.length-r.count} remaining semesters. Expected grades do not limit this maximum.`;$('progress').textContent=`${r.count??0} of ${rows.length} semesters completed`;$('projection-note').textContent=r.projected!=null?'Based on all your actual and expected grades.':'Fill all semesters with actual or expected GPAs to see your projection.';$('meter-fill').style.width=`${r.invalid?0:r.maximum/state.scale*100}%`;$('method').textContent=state.weighted?'CGPA = sum of (semester GPA × credit units) ÷ total credit units. Enter credits for future semesters too.':'Each semester counts equally. If your semester credit totals differ, enable credit units for a weighted estimate.';try{localStorage.setItem('cgpa-plan',JSON.stringify(state))}catch{$('saved').textContent='Browser storage is unavailable. Keep this tab open to retain your plan.'}}
$('years').onchange=e=>{state.years=Number(e.target.value);render()};$('scale').onchange=e=>{state.scale=Number(e.target.value);render()};$('weighted').onchange=e=>{state.weighted=e.target.checked;render()};$('reset').onclick=()=>{state.rows=Array.from({length:12},blank);render()};$('example').onclick=()=>{state.years=3;state.scale=5;state.rows=Array.from({length:12},blank);state.rows[0]={gpa:'4.53',type:'actual',credits:'20'};state.rows[1]={gpa:'4.76',type:'actual',credits:'20'};render()};render();

